  function openReadyCrew(done){const exhausted=player().crew.filter(x=>x.exhausted);if(!exhausted.length){done('No exhausted Crew to recover.');return}readyResolver=done;readySelected.clear();openPlayerDrawer();toast('Select up to 2 Exhausted Crew to Ready.')}
  function confirmReady(){const p=player();p.crew.forEach(c=>{if(readySelected.has(c.uid))c.exhausted=false});const n=readySelected.size;saveBoard();updateHud();finishReady(`Readied ${n} Crew.`)}
