  function toggleTreasureActive(id){if(game.expedition)return toast('Treasures are locked until this Expedition ends.');const p=player(),i=p.activeTreasures.indexOf(id);if(i>=0)p.activeTreasures.splice(i,1);else if(p.activeTreasures.length<3)p.activeTreasures.push(id);else{toast('All 3 Active Treasure slots are full.');return}saveBoard();renderPlayerDrawer();updateHud()}
