  window.CaptainsDashCards={grantTreasure(id){if(!game||!treasureById[id])return false;const p=player();if(!p.treasures.includes(id))p.treasures.push(id);saveBoard();updateHud();renderPlayerDrawer();return true},exhaustCrew(uid){if(!game)return false;const c=player().crew.find(x=>x.uid===uid)||player().crew.find(x=>x.id===uid);if(!c)return false;c.exhausted=true;saveBoard();updateHud();renderPlayerDrawer();return true},_debugState(){return game?JSON.parse(JSON.stringify({current:game.current,phase:game.phase,player:player()})):null},crewData:CREW,treasureData:TREASURES};
